/**
 * Mark As Done: the ticket exists, so the email goes to the folder "erledigt".
 * @returns {Array<{json: {messageId: string, folderLabelId: string}}>}
 */
const email = $('Check Daily Limit').first().json;
return [{ json: { messageId: email.messageId, folderLabelId: email.doneLabelId } }];

/**
 * Mark For Review: limit reached or processing failed, so the email goes to the folder "zu bearbeiten".
 * @returns {Array<{json: {messageId: string, folderLabelId: string}}>}
 */
const email = $('Check Daily Limit').first().json;
return [{ json: { messageId: email.messageId, folderLabelId: email.reviewLabelId } }];
